<?php
namespace Cyberfort\AIRegister; defined( 'ABSPATH' ) || exit;
class Plugin { public function init(): void { require_once CFAIR_PATH . 'includes/helpers.php'; ( new Settings() )->init(); ( new Routes() )->init(); ( new Shortcodes() )->init(); ( new Blocks() )->init(); add_action( 'wp_enqueue_scripts', [ $this, 'assets' ] ); add_action( 'admin_notices', [ $this, 'activation_notice' ] ); } public function assets(): void { wp_register_style( 'cfair-public', CFAIR_URL . 'assets/css/public.css', [], CFAIR_VERSION ); } public function activation_notice(): void { if ( get_transient( 'cfair_activation_notice' ) && current_user_can( 'manage_options' ) ) { delete_transient( 'cfair_activation_notice' ); echo '<div class="notice notice-info"><p>' . wp_kses_post( sprintf( __( 'Cyberfort AI Register is ready. <a href="%s">Configure the connection</a>.', 'cyberfort-ai-register' ), esc_url( admin_url( 'options-general.php?page=cyberfort-ai-register' ) ) ) ) . '</p></div>'; } } }
